/**
 * Shader of the triangulation.
 *
 * ## The mathematical idea
 *
 * A grid of cells, each cut in two by a diagonal. The diagonal alternates
 * from one cell to the next — in a chequerboard — without which the tiling
 * would have a dominant direction and the facets would form stripes. The side
 * of the diagonal the fragment falls on gives the facet; a stable draw on the
 * identifier of the facet gives its phase.
 *
 * The lighting combines two movements: a slow breathing of each facet's own,
 * and a diagonal sweep that crosses the tiling — like a reflection sliding
 * over a crystal. The first on its own would make a shimmer with no
 * direction; the second on its own, a plain wave. Together, the facets seem
 * to receive a light that moves, and each answers it in its own way.
 *
 * The edges are read by distance: to the diagonal, to the borders of the
 * cell. They are tinted towards the background, so that they read as joints,
 * not as strokes.
 *
 * ## Uniforms
 *
 * - `uTime` — time in seconds, supplied by the engine.
 * - `uResolution` — canvas size in pixels, supplied by the engine.
 * - `uColorA` — the background, and the joints.
 * - `uColorB` — the lit facets.
 * - `uColorC` — the tint of the brightest facets.
 * - `uSize` — number of cells over the height.
 * - `uSpeed` — speed of the lighting.
 * - `uContrast` — gap between dark and light facets.
 * - `uTint` — weight of the tint on the brightest facets.
 */
export const TRIANGLES_FRAGMENT = /* glsl */ `
precision highp float;

varying vec2 vUv;

uniform float uTime;
uniform vec2 uResolution;
uniform vec3 uColorA;
uniform vec3 uColorB;
uniform vec3 uColorC;
uniform float uSize;
uniform float uSpeed;
uniform float uContrast;
uniform float uTint;

// Pseudo-random number, stable per facet.
float hash(vec2 cell) {
  return fract(sin(dot(cell, vec2(127.1, 311.7))) * 43758.5453);
}

void main() {
  float aspect = uResolution.x / max(uResolution.y, 1.0);
  float size = clamp(uSize, 2.0, 40.0);
  vec2 p = vUv * vec2(aspect, 1.0) * size;

  // One pixel, in cell units.
  float px = size / max(uResolution.y, 1.0);

  vec2 id = floor(p);
  vec2 f = fract(p);

  // The diagonal alternates in a chequerboard: the tiling has no dominant
  // direction.
  float flip = mod(id.x + id.y, 2.0);
  float diagonal = mix(f.x - f.y, f.x + f.y - 1.0, flip);
  float side = step(0.0, diagonal);
  vec2 facet = id * 2.0 + vec2(side, 0.0);
  float seed = hash(facet);

  // The lighting: a breathing of the facet's own, and a diagonal sweep that
  // crosses the tiling.
  float own = 0.5 + 0.5 * sin(uTime * uSpeed * (0.4 + 0.6 * seed) + seed * 6.2832);
  float sweep = 0.5 + 0.5 * sin((id.x - id.y * 0.6) * 0.5 - uTime * uSpeed * 0.8);
  float light = mix(own, sweep, 0.45);

  // The edges: the diagonal and the borders of the cell, a thin line.
  float toDiagonal = abs(diagonal) * 0.7071;
  vec2 toEdge = min(f, 1.0 - f);
  float edge = min(toDiagonal, min(toEdge.x, toEdge.y));
  float joint = 1.0 - smoothstep(px * 0.3, px * 1.2, edge);

  float contrast = clamp(uContrast, 0.0, 1.0);
  vec3 colour = mix(uColorA, uColorB, (0.15 + 0.85 * light) * contrast);
  colour = mix(colour, uColorC, clamp(uTint, 0.0, 1.0) * pow(light, 4.0) * (0.4 + 0.6 * seed));
  colour = mix(colour, uColorA, joint * 0.6);

  gl_FragColor = vec4(colour, 1.0);
}
`

sources.component.tsx:
/**
 * Triangulation: a tiling of triangular facets whose lighting moves, like a
 * light sliding over a crystal.
 *
 * ## The principle
 *
 * Every cell of the grid is cut by a diagonal, alternating in a chequerboard
 * so that the tiling has no dominant direction. The lighting of a facet
 * combines a breathing of its own and a diagonal sweep that crosses the whole
 * tiling; the brightest ones take on a tint.
 *
 * What sets this entry apart from `mosaic` and from `cells`: the facets are
 * fixed triangles, and it is the light that moves, not the tiling.
 *
 * ## What this component delegates
 *
 * It carries only what sets it apart: its shader, its settings and its
 * fallback. Reading the tokens, converting them to floats and re-reading them
 * when the theme changes all come from the engine — copying that here would
 * leave as many versions to maintain as there are backgrounds.
 *
 * The fallback is not a precaution: it is shown while the backend loads, when
 * WebGL is missing, when the arbiter refuses the surface — it grants only one
 * per backend — and under reduced motion.
 *
 * @module
 */

import {
  mergePresentation,
  useOnReady,
  useTokenShader,
  type Customisable,
  type ReadyCallback,
  type ShaderColour,
} from '@odoro-cli/engine'
import { type ReactElement } from 'react'

import { TRIANGLES_FRAGMENT } from './triangles.shader.js'

/** What the escape hatch receives. */
export interface TrianglesControls {
  /** Colours actually handed to the shader. */
  readonly colours: readonly ShaderColour[]
  /** Reason for the refusal, if there is one. */
  readonly refused: string | undefined
}

/** Props specific to this component. */
export interface TrianglesOwnProps {
  /** Number of cells over the height. Capped at forty by the shader. @defaultValue 7 */
  size?: number
  /** Speed of the lighting. @defaultValue 0.5 */
  speed?: number
  /** Gap between dark and light facets. @defaultValue 0.8 */
  contrast?: number
  /** Weight of the tint on the brightest facets. @defaultValue 0.6 */
  tint?: number
  /** Tokens whose colours are read. */
  colors?: readonly string[]
  /** Fallback classes. */
  fallback?: string
  /** Escape hatch. */
  onReady?: ReadyCallback<TrianglesControls>
}

/** All props. */
export type TrianglesProps = Customisable<TrianglesOwnProps>

/** Tokens used by default: the background, the facets, the tint of the brightest. */
const DEFAULT_TOKENS = [
  '--o-theme-bg',
  '--o-theme-line',
  '--o-palette-violet-500',
] as const

/** Default fallback: a frozen tint, in the same tones. */
const DEFAULT_FALLBACK = 'o-bg-zinc-50 dark:o-bg-zinc-950'

/**
 * Triangulation.
 *
 * @example
 * <div className="o-relative o-min-h-screen">
 *   <Triangles className="o-absolute o-inset-0" />
 *   <main className="o-relative">…</main>
 * </div>
 */
export function Triangles({
  size = 7,
  speed = 0.5,
  contrast = 0.8,
  tint = 0.6,
  colors = DEFAULT_TOKENS,
  fallback = DEFAULT_FALLBACK,
  onReady,
  ...rest
}: TrianglesProps): ReactElement {
  const { ref, setHost, ready, refused, colours } = useTokenShader<HTMLDivElement>({
    fragment: TRIANGLES_FRAGMENT,
    colors,
    uniforms: { uSize: size, uSpeed: speed, uContrast: contrast, uTint: tint },
    name: 'triangles',
    // Thin joints between small facets shimmer at a reduced pixel density: at
    // low quality, the cells widen.
    degrade: (quality) => ({
      uSize: quality === 'low' ? Math.min(size, 6) : size,
    }),
  })

  useOnReady(onReady, ready ? { colours, refused } : null, ref.current)

  const { className, style } = mergePresentation(
    { className: 'o-relative o-overflow-hidden' },
    rest,
  )

  return (
    <div
      {...rest}
      ref={(element) => {
        setHost(element)
        ref.current = element
      }}
      className={className}
      style={style}
      aria-hidden
    >
      {ready && refused === undefined ? null : (
        <div className={`o-absolute o-inset-0 ${fallback}`} />
      )}
    </div>
  )
}
